window.BOOK={"key":"maqsud","app":"mutoon","lsk":"mutoon_maqsud_v1","title":"المقصود","unitWord":"فقرة","sub":"المقصود في علم التصريف · مجهول المؤلف (يُنسب لأبي حنيفة ت ١٥٠هـ) · ١١ بابًا","source":"https://archive.org/details/majmou3_sarf («مجموعة الصرف وشروحها وحواشيها»: متن «المقصود» مشكولًا، ص 385–404 من المطبوع = صور الصفحات n387–n406؛ نُقل نصه وشكله من صور الصفحات) · قوبل بـ: takw.in «المقصود في علم الصرف» (نص مكتوب) + archive.org «إزالة القيود عن ألفاظ المقصود» لعبد الملك السعدي (صور الصفحات والنص المستخرج آليًّا منها) — مقابلة آلية كلمةً كلمة؛ انظر maqsud-sources.md","note":"النص والشكل منقولان من صور صفحات المتن المشكول في «مجموعة الصرف»، وقوبل لفظه آليًّا بنص «تكوين الراسخين» وبمتن «إزالة القيود» لعبد الملك السعدي. ونسبته لأبي حنيفة مشهورة غير ثابتة، والأكثر أنه مجهول المؤلف.","chapters":[{"id":"ma1","title":"الْمُقَدِّمَةُ","units":[{"id":"ma1_1","label":"الْمُقَدِّمَةُ · ١","segs":[["matn","الْحَمْدُ لِلَّهِ الْوَهَّابِ لِلْمُؤْمِنِينَ سَبِيلَ الصَّوَابِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى نَبِيِّهِ مُحَمَّدٍ الزَّاجِرِ عَنِ الْإِذْنَابِ، الْحَاثِّ عَلَى طَلَبِ الثَّوَابِ، وَعَلَى آلِهِ وَأَصْحَابِهِ خَيْرِ الْآلِ وَخَيْرِ الْأَصْحَابِ."]]},{"id":"ma1_2","label":"الْمُقَدِّمَةُ · ٢","segs":[["matn","أَمَّا بَعْدُ: فَإِنَّ الْعَرَبِيَّةَ وَسِيلَةٌ إِلَى الْعُلُومِ الشَّرْعِيَّةِ، وَأَحَدُ أَرْكَانِهَا: التَّصْرِيفُ؛ لِأَنَّهُ بِهِ يَصِيرُ الْقَلِيلُ مِنَ الْأَفْعَالِ كَثِيرًا، وَاللَّهُ الْمُوَفِّقُ وَالْمُرْشِدُ."]]}]},{"id":"ma2","title":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ","units":[{"id":"ma2_1","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١","segs":[["matn","الْأَفْعَالُ عَلَى ضَرْبَيْنِ: أَصْلِيٌّ، وَذُو زِيَادَةٍ. فَالْأَصْلِيُّ: ثُلَاثِيٌّ، وَرُبَاعِيٌّ:"]]},{"id":"ma2_2","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ٢","segs":[["matn","فَالثُّلَاثِيُّ: مَا كَانَ مَاضِيهِ مُشْتَمِلًا عَلَى ثَلَاثَةِ أَحْرُفٍ، وَهُوَ سِتَّةُ أَبْوَابٍ:"]]},{"id":"ma2_3","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ٣","segs":[["matn","الْأَوَّلُ: فَعَلَ يَفْعُلُ، بِفَتْحِ الْعَيْنِ فِي الْمَاضِي، وَضَمِّهَا فِي الْغَابِرِ."]]},{"id":"ma2_4","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ٤","segs":[["matn","وَالثَّانِي: فَعَلَ يَفْعِلُ، بِفَتْحِ الْعَيْنِ فِي الْمَاضِي، وَكَسْرِهَا فِي الْغَابِرِ."]]},{"id":"ma2_5","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ٥","segs":[["matn","وَالثَّالِثُ: فَعَلَ يَفْعَلُ، بِفَتْحِ الْعَيْنِ فِي الْمَاضِي وَالْغَابِرِ."]]},{"id":"ma2_6","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ٦","segs":[["matn","وَالرَّابِعُ: فَعِلَ يَفْعَلُ، بِكَسْرِ الْعَيْنِ فِي الْمَاضِي، وَفَتْحِهَا فِي الْغَابِرِ."]]},{"id":"ma2_7","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ٧","segs":[["matn","وَالْخَامِسُ: فَعُلَ يَفْعُلُ، بِضَمِّ الْعَيْنِ فِي الْمَاضِي وَالْغَابِرِ."]]},{"id":"ma2_8","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ٨","segs":[["matn","وَالسَّادِسُ: فَعِلَ يَفْعِلُ، بِكَسْرِ الْعَيْنِ فِي الْمَاضِي وَالْغَابِرِ."]]},{"id":"ma2_9","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ٩","segs":[["matn","وَمَا كَانَ مُخْتَصًّا بِالْبَابِ الثَّالِثِ لَا يَكُونُ عَيْنُهُ أَوْ لَامُهُ إِلَّا حَرْفًا مِنْ حُرُوفِ الْحَلْقِ، إِلَّا أَبَى يَأْبَى فَهُوَ شَاذٌّ."]]},{"id":"ma2_10","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١٠","segs":[["matn","وَحُرُوفُ الْحَلْقِ سِتَّةٌ: الْحَاءُ وَالْخَاءُ، وَالْعَيْنُ وَالْغَيْنُ، وَالْهَاءُ وَالْهَمْزَةُ."]]},{"id":"ma2_11","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١١","segs":[["matn","وَالرُّبَاعِيُّ الْمُجَرَّدُ: مَا كَانَ مَاضِيهِ عَلَى أَرْبَعَةِ أَحْرُفٍ، وَهُوَ بَابُ فَعْلَلَ، مِثْلُ: دَحْرَجَ، وَهُوَ بَابٌ وَاحِدٌ."]]},{"id":"ma2_12","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١٢","segs":[["matn","وَقَدْ يَكُونُ سِتَّةَ أَبْوَابٍ، وَيُقَالُ لَهَا: الْمُلْحَقُ بِالرُّبَاعِيِّ: وَهُوَ بَابُ فَوْعَلَ، نَحْوُ: حَوْقَلَ، وَفَعْوَلَ، نَحْوُ: جَهْوَرَ، وَفَيْعَلَ، نَحْوُ: بَيْطَرَ، وَفَعْيَلَ، نَحْوُ: عَثْيَرَ، وَفَعْلَى، نَحْوُ: سَلْقَى، وَفَعْلَلَ، نَحْوُ: جَلْبَبَ."]]},{"id":"ma2_13","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١٣","segs":[["matn","وَأَمَّا الْمَزِيدُ فِيهِ فَنَوْعَانِ: مَزِيدٌ عَلَى الثُّلَاثِيِّ، وَمَزِيدٌ عَلَى الرُّبَاعِيِّ."]]},{"id":"ma2_14","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١٤","segs":[["matn","فَمَزِيدُ الثُّلَاثِيِّ: أَرْبَعَةَ عَشَرَ بَابًا، وَهِيَ ثَلَاثَةُ أَنْوَاعٍ: رُبَاعِيٌّ، وَخُمَاسِيٌّ، وَسُدَاسِيٌّ."]]},{"id":"ma2_15","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١٥","segs":[["matn","فَالرُّبَاعِيُّ عَلَى ثَلَاثَةِ أَبْوَابٍ: أَفْعَلَ، نَحْوُ: أَكْرَمَ، وَفَعَّلَ بِتَشْدِيدِ الْعَيْنِ، نَحْوُ: فَرَّحَ، وَفَاعَلَ، نَحْوُ: قَاتَلَ."]]},{"id":"ma2_16","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١٦","segs":[["matn","وَالْخُمَاسِيُّ خَمْسَةُ أَبْوَابٍ: انْفَعَلَ، نَحْوُ: انْقَطَعَ، وَافْتَعَلَ، نَحْوُ: اجْتَمَعَ، وَافْعَلَّ، نَحْوُ: اشْتَدَّ، بِتَشْدِيدِ اللَّامِ، وَتَفَعَّلَ، نَحْوُ: تَكَسَّرَ، بِتَشْدِيدِ الْعَيْنِ، وَتَفَاعَلَ، نَحْوُ: تَبَاعَدَ."]]},{"id":"ma2_17","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١٧","segs":[["matn","وَالسُّدَاسِيُّ سِتَّةُ أَبْوَابٍ: اسْتَفْعَلَ، نَحْوُ: اسْتَخْرَجَ، وَافْعَوْعَلَ، نَحْوُ: اعْشَوْشَبَ، وَافْعَوَّلَ، نَحْوُ: اجْلَوَّذَ، بِتَشْدِيدِ الْوَاوِ، وَافْعَنْلَلَ، نَحْوُ: اقْعَنْسَسَ، وَافْعَنْلَى، نَحْوُ: اسْلَنْقَى، وَافْعَالَّ، نَحْوُ: احْمَارَّ، بِتَشْدِيدِ اللَّامِ."]]},{"id":"ma2_18","label":"الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِيهِ · ١٨","segs":[["matn","وَمَزِيدُ الرُّبَاعِيِّ ثَلَاثَةُ أَبْوَابٍ: افْعَنْلَلَ، نَحْوُ: احْرَنْجَمَ، وَافْعَلَلَّ، نَحْوُ: اقْشَعَرَّ بِتَشْدِيدِ اللَّامِ الْأَخِيرَةِ، وَتَفَعْلَلَ، نَحْوُ: تَدَحْرَجَ، يَتَدَحْرَجُ، تَدَحْرُجًا."]]}]},{"id":"ma3","title":"الْمَصْدَرُ","units":[{"id":"ma3_1","label":"الْمَصْدَرُ · ١","segs":[["matn","وَهِيَ سِتَّةٌ: الْمَاضِي، وَالْمُضَارِعُ، وَالْأَمْرُ، وَالنَّهْيُ، وَالْفَاعِلُ، وَالْمَفْعُولُ."]]},{"id":"ma3_2","label":"الْمَصْدَرُ · ٢","segs":[["matn","وَأَمَّا الْمَصْدَرُ: فَلَا يَخْلُو مِنْ أَنْ يَكُونَ مِيمِيًّا، أَوْ غَيْرَ مِيمِيٍّ."]]},{"id":"ma3_3","label":"الْمَصْدَرُ · ٣","segs":[["matn","فَإِنْ كَانَ الْمَصْدَرُ غَيْرَ مِيمِيٍّ؛ فَهُوَ سَمَاعِيٌّ. وَنَعْنِي بِالسَّمَاعِيِّ: أَنَّهُ يُحْفَظُ كُلُّ مَصْدَرٍ عَلَى مَا جَاءَ مِنَ الْعَرَبِ، فَلَا يُقَاسُ عَلَيْهِ؛ لِأَنَّهُ لَا قِيَاسَ لِمَصْدَرٍ ثُلَاثِيٍّ، وَمَصْدَرُ غَيْرِ الثُّلَاثِيِّ قِيَاسِيٌّ."]]},{"id":"ma3_4","label":"الْمَصْدَرُ · ٤","segs":[["matn","فَإِنْ كَانَ مِيمِيًّا؛ فَيُنْظَرُ فِي عَيْنِ الْفِعْلِ الْمُضَارِعِ:"]]},{"id":"ma3_5","label":"الْمَصْدَرُ · ٥","segs":[["matn","فَإِنْ كَانَ مَفْتُوحًا أَوْ مَضْمُومًا: فَالْمَصْدَرُ الْمِيمِيُّ، وَالزَّمَانُ، وَالْمَكَانُ مِنْهُ: مَفْعَلٌ بِفَتْحِ الْمِيمِ وَالْعَيْنِ، وَسُكُونِ الْفَاءِ."]]},{"id":"ma3_6","label":"الْمَصْدَرُ · ٦","segs":[["matn","إِلَّا مَا شَذَّ، نَحْوُ: الْمَطْلِعِ، وَالْمَغْرِبِ، وَالْمَسْجِدِ، وَالْمَنْسِكِ، وَالْمَشْرِقِ، وَالْمَجْزِرِ، وَالْمَسْكِنِ، وَالْمَنْبِتِ، وَالْمَفْرِقِ، وَالْمَحْشِرِ، وَالْمَسْقِطِ، وَالْمَجْمِعِ بِكَسْرِ الْعَيْنِ فِي الْجَمِيعِ، وَإِنْ كَانَ الْقِيَاسُ عَلَى الْفَتْحِ."]]},{"id":"ma3_7","label":"الْمَصْدَرُ · ٧","segs":[["matn","وَإِنْ كَانَ مَكْسُورَ الْعَيْنِ: فَالْمَصْدَرُ الْمِيمِيُّ مِنْهُ عَلَى وَزْنِ مَفْعَلٌ، بِفَتْحِ الْمِيمِ وَالْعَيْنِ، وَسُكُونِ الْفَاءِ، إِلَّا الْمَرْجِعَ، وَالْمَصِيرَ؛ فَإِنَّهُمَا مَصْدَرَانِ وَقَدْ جَاءَا بِكَسْرِ الْعَيْنِ."]]},{"id":"ma3_8","label":"الْمَصْدَرُ · ٨","segs":[["matn","وَالزَّمَانُ وَالْمَكَانُ مِنْهُ عَلَى وَزْنِ: مَفْعِلٌ بِكَسْرِ الْعَيْنِ، هَذَا فِي الصَّحِيحِ، وَالْأَجْوَفِ، وَالْمُضَاعَفِ، وَالْمَهْمُوزِ."]]},{"id":"ma3_9","label":"الْمَصْدَرُ · ٩","segs":[["matn","وَأَمَّا فِي النَّاقِصِ: فَالْمَصْدَرُ الْمِيمِيُّ وَالزَّمَانُ وَالْمَكَانُ مِنْهُ عَلَى وَزْنِ مَفْعَلٌ، بِفَتْحِ الْمِيمِ وَالْعَيْنِ، وَسُكُونِ الْفَاءِ مِنْ جَمِيعِ الْأَبْوَابِ."]]},{"id":"ma3_10","label":"الْمَصْدَرُ · ١٠","segs":[["matn","وَفِي الْمُعْتَلِّ الْفَاءِ: فَالْمَصْدَرُ الْمِيمِيُّ وَالزَّمَانُ وَالْمَكَانُ مِنْهُ عَلَى وَزْنِ مَفْعِلٌ بِكَسْرِ الْعَيْنِ مِنْ جَمِيعِ الْأَبْوَابِ، وَاللَّفِيفُ الْمَقْرُونُ كَالنَّاقِصِ، وَاللَّفِيفُ الْمَفْرُوقُ كَالْمُعْتَلِّ الْفَاءِ."]]},{"id":"ma3_11","label":"الْمَصْدَرُ · ١١","segs":[["matn","وَإِنْ كَانَ الْفِعْلُ زَائِدًا عَلَى الثُّلَاثِيِّ؛ فَالْمَصْدَرُ الْمِيمِيُّ وَالزَّمَانُ وَالْمَكَانُ وَالْمَفْعُولُ مِنْ كُلِّ بَابٍ يَكُونُ عَلَى وَزْنِ الْمُضَارِعِ الْمَجْهُولِ مِنْ ذَلِكَ الْبَابِ."]]},{"id":"ma3_12","label":"الْمَصْدَرُ · ١٢","segs":[["matn","إِلَّا أَنَّكَ تُبْدِلُ حَرْفَ الْمُضَارَعَةِ بِالْمِيمِ الْمَضْمُومَةِ، وَتَفْتَحُ مَا قَبْلَ آخِرِهِ، وَالْفَاعِلُ مِنْهُ يَكُونُ بِكَسْرِ مَا قَبْلَ آخِرِهِ."]]}],"group":"فَصْلٌ فِي الْوُجُوهِ الَّتِي اشْتَدَّتِ الْحَاجَةُ إِلَى إِخْرَاجِهَا مِنَ الْمَصْدَرِ"},{"id":"ma4","title":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي","units":[{"id":"ma4_1","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ١","segs":[["matn","وَأَمَّا الْمَاضِي: فَلَا يَخْلُو مِنْ أَنْ يَكُونَ الْفِعْلُ مَعْرُوفًا، أَوْ مَجْهُولًا."]]},{"id":"ma4_2","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ٢","segs":[["matn","فَإِنْ كَانَ مَعْرُوفًا: فَالْحَرْفُ الْأَخِيرُ مِنَ الْمَاضِي مَبْنِيٌّ عَلَى الْفَتْحِ فِي الْوَاحِدِ، وَالتَّثْنِيَةِ؛ سَوَاءٌ كَانَ مُذَكَّرًا أَوْ مُؤَنَّثًا، وَمَضْمُومٌ فِي جَمْعِ الْمُذَكَّرِ الْغَائِبِ، وَسَاكِنٌ فِي الْبَوَاقِي عِنْدَ اتِّصَالِهِ بِالنُّونِ وَالتَّاءِ مِنْ جَمِيعِ الْأَبْوَابِ."]]},{"id":"ma4_3","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ٣","segs":[["matn","وَالْحَرْفُ الْأَوَّلُ مِنَ الْمَاضِي مَفْتُوحٌ مِنْ جَمِيعِ الْأَبْوَابِ، إِلَّا مِنْ أَبْوَابِ الْخُمَاسِيِّ وَالسُّدَاسِيِّ الَّتِي فِي أَوَّلِهَا هَمْزَةُ وَصْلٍ."]]},{"id":"ma4_4","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ٤","segs":[["matn","وَهَمْزَةُ الْوَصْلِ تَثْبُتُ فِي الِابْتِدَاءِ، وَتَسْقُطُ فِي الدَّرْجِ."]]},{"id":"ma4_5","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ٥","segs":[["matn","وَهَمْزَةُ الْوَصْلِ هَمْزَةُ: ابْنٍ، وَابْنِمٍ، وَابْنَةٍ، وَامْرِئٍ، وَامْرَأَةٍ، وَاثْنَيْنِ، وَاثْنَتَيْنِ، وَاسْمٍ، وَاسْتٍ، وَايْمُنٍ."]]},{"id":"ma4_6","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ٦","segs":[["matn","وَهَمْزَةُ الْمَاضِي، وَالْمَصْدَرِ، وَالْأَمْرِ مِنَ الْخُمَاسِيِّ وَالسُّدَاسِيِّ، وَأَمْرِ الْحَاضِرِ مِنَ الثُّلَاثِيِّ، وَالْهَمْزَةُ الْمُتَّصِلَةُ بِلَامِ التَّعْرِيفِ."]]},{"id":"ma4_7","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ٧","segs":[["matn","وَهَمْزَةُ الْوَصْلِ مَحْذُوفَةٌ فِي الْوَصْلِ، وَمَكْسُورَةٌ فِي الِابْتِدَاءِ، إِلَّا مَا اتَّصَلَتْ بِلَامِ التَّعْرِيفِ، وَهَمْزَةَ ايْمُنٍ؛ فَإِنَّهُمَا مَفْتُوحَتَانِ فِي الِابْتِدَاءِ."]]},{"id":"ma4_8","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ٨","segs":[["matn","وَمَا يَكُونُ فِي أَوَّلِ الْأَمْرِ مِنْ يَفْعُلُ بِضَمِّ الْعَيْنِ؛ فَإِنَّهَا مَضْمُومَةٌ فِي الِابْتِدَاءِ تَبَعًا لِلْعَيْنِ، وَكَذَلِكَ مَضْمُومَةٌ فِي الْمَاضِي الْمَجْهُولِ مِنَ الْخُمَاسِيِّ، وَالسُّدَاسِيِّ."]]},{"id":"ma4_9","label":"الْأَوَّلُ: الْفِعْلُ الْمَاضِي · ٩","segs":[["matn","وَإِنْ كَانَ الْفِعْلُ مَجْهُولًا: فَالْحَرْفُ الْأَخِيرُ مِنْهُ يَكُونُ مِثْلَ مَا كَانَ فِي الْمَعْرُوفِ، وَالْحَرْفُ الَّذِي قَبْلَ الْأَخِيرِ مَكْسُورٌ، وَالسَّاكِنُ سَاكِنٌ عَلَى حَالِهِ، وَمَا بَقِيَ مَضْمُومٌ."]]}],"group":"فَصْلٌ فِي الْوُجُوهِ الَّتِي اشْتَدَّتِ الْحَاجَةُ إِلَى إِخْرَاجِهَا مِنَ الْمَصْدَرِ"},{"id":"ma5","title":"الثَّانِي: الْفِعْلُ الْمُضَارِعُ","units":[{"id":"ma5_1","label":"الثَّانِي: الْفِعْلُ الْمُضَارِعُ · ١","segs":[["matn","وَأَمَّا الْمُضَارِعُ: فَهُوَ الْفِعْلُ الَّذِي فِي أَوَّلِهِ حَرْفٌ مِنْ حُرُوفِ أَتَيْنَ، بِشَرْطِ أَنْ يَكُونَ ذَلِكَ الْحَرْفُ زَائِدًا عَلَى الْمَاضِي."]]},{"id":"ma5_2","label":"الثَّانِي: الْفِعْلُ الْمُضَارِعُ · ٢","segs":[["matn","وَحَرْفُ الْمُضَارَعَةِ مَفْتُوحٌ فِي الْمَعْرُوفِ مِنْ جَمِيعِ الْأَبْوَابِ، إِلَّا مِنَ الرُّبَاعِيِّ أَيَّ رُبَاعِيٍّ كَانَ؛ فَإِنَّهَا مَضْمُومَةٌ فِيهِنَّ."]]},{"id":"ma5_3","label":"الثَّانِي: الْفِعْلُ الْمُضَارِعُ · ٣","segs":[["matn","وَمَا قَبْلَ لَامِ الْفِعْلِ الْمُضَارِعِ مَكْسُورَةٌ فِي الرُّبَاعِيِّ وَالْخُمَاسِيِّ وَالسُّدَاسِيِّ، إِلَّا مِنْ يَتَفَعَّلُ، وَيَتَفَاعَلُ، وَيَتَفَعْلَلُ؛ فَإِنَّهَا مَفْتُوحَةٌ فِيهِنَّ."]]},{"id":"ma5_4","label":"الثَّانِي: الْفِعْلُ الْمُضَارِعُ · ٤","segs":[["matn","وَفِي الْمَجْهُولِ حَرْفُ الْمُضَارَعَةِ مَضْمُومٌ، وَمَا قَبْلَ لَامِ الْفِعْلِ الْمُضَارِعِ مَفْتُوحَةٌ، وَالسَّاكِنُ سَاكِنٌ عَلَى حَالِهِ، وَمَا بَقِيَ مَفْتُوحٌ كُلُّهُ."]]},{"id":"ma5_5","label":"الثَّانِي: الْفِعْلُ الْمُضَارِعُ · ٥","segs":[["matn","مَا عَدَا لَامَ الْفِعْلِ الْمُضَارِعِ؛ فَإِنَّهَا مَرْفُوعَةٌ فِي الْمَعْرُوفِ وَالْمَجْهُولِ، مَا لَمْ يَكُنْ حَرْفٌ نَاصِبٌ يَنْصِبُهَا، أَوْ جَازِمٌ يَجْزِمُهَا."]]}],"group":"فَصْلٌ فِي الْوُجُوهِ الَّتِي اشْتَدَّتِ الْحَاجَةُ إِلَى إِخْرَاجِهَا مِنَ الْمَصْدَرِ"},{"id":"ma6","title":"الثَّالِثُ وَالرَّابِعُ: الْأَمْرُ وَالنَّهْيُ","units":[{"id":"ma6_1","label":"الثَّالِثُ وَالرَّابِعُ: الْأَمْرُ وَالنَّهْيُ · ١","segs":[["matn","وَأَمَّا الْأَمْرُ، وَالنَّهْيُ: فَإِنَّهُمَا يَكُونَانِ عَلَى لَفْظِ الْمُضَارِعِ، إِلَّا أَنَّهُمَا مَجْزُومَانِ."]]},{"id":"ma6_2","label":"الثَّالِثُ وَالرَّابِعُ: الْأَمْرُ وَالنَّهْيُ · ٢","segs":[["matn","وَعَلَامَةُ الْجَزْمِ فِيهِمَا: سُقُوطُ نُونِ التَّثْنِيَةِ، وَجَمْعِ الْمُذَكَّرِ، وَوَاحِدَةِ الْمُخَاطَبَةِ، وَفِي الْبَوَاقِي سُكُونُ لَامِ الْفِعْلِ الصَّحِيحَةِ، وَسُقُوطُ لَامِ الْفِعْلِ الْمُعْتَلِّ."]]},{"id":"ma6_3","label":"الثَّالِثُ وَالرَّابِعُ: الْأَمْرُ وَالنَّهْيُ · ٣","segs":[["matn","سِوَى نُونِ جَمْعِ الْمُؤَنَّثِ، فَإِنَّ نُونَهَا ثَابِتَةٌ فِي الْجَزْمِ وَغَيْرِهِ."]]},{"id":"ma6_4","label":"الثَّالِثُ وَالرَّابِعُ: الْأَمْرُ وَالنَّهْيُ · ٤","segs":[["matn","وَأَمْرُ الْحَاضِرِ فِي الْمَعْرُوفِ مِنَ الْمُضَارِعِ: أَنْ تَحْذِفَ مِنْهُ حَرْفَ الْمُضَارَعَةِ، وَتُدْخِلَ عَلَيْهِ هَمْزَةَ الْوَصْلِ إِنْ كَانَ مَا بَعْدَ حَرْفِ الْمُضَارَعَةِ سَاكِنًا؛ لِتَعَذُّرِ الِابْتِدَاءِ بِالسَّاكِنِ، نَحْوُ: اضْرِبْ، فَيُبْدَأُ بِهَا."]]},{"id":"ma6_5","label":"الثَّالِثُ وَالرَّابِعُ: الْأَمْرُ وَالنَّهْيُ · ٥","segs":[["matn","وَإِنْ كَانَ مَا بَعْدَ حَرْفِ الْمُضَارَعَةِ مُتَحَرِّكًا؛ فَتُسَكِّنُ آخِرَهُ، فَتَقُولُ مِنْ تُحَاسِبُ: حَاسِبْ، بَعْدَ حَذْفِ حَرْفِ الْمُضَارَعَةِ، وَهُوَ مَبْنِيٌّ عَلَى الْوَقْفِ، وَالْمَبْنِيُّ عَلَى الْوَقْفِ كَالْمَجْزُومِ فِي اللَّفْظِ."]]}],"group":"فَصْلٌ فِي الْوُجُوهِ الَّتِي اشْتَدَّتِ الْحَاجَةُ إِلَى إِخْرَاجِهَا مِنَ الْمَصْدَرِ"},{"id":"ma7","title":"الْخَامِسُ: اسْمُ الْفَاعِلِ","units":[{"id":"ma7_1","label":"الْخَامِسُ: اسْمُ الْفَاعِلِ · ١","segs":[["matn","وَأَمَّا الْفَاعِلُ: فَيُنْظَرُ فِي عَيْنِ الْفِعْلِ الْمَاضِي: فَإِنْ كَانَ مَفْتُوحًا، فَوَزْنُهُ: نَاصِرٌ."]]},{"id":"ma7_2","label":"الْخَامِسُ: اسْمُ الْفَاعِلِ · ٢","segs":[["matn","وَإِنْ كَانَ مَضْمُومًا، فَوَزْنُهُ: عَظِيمٌ، وَضَخْمٌ، وَإِنْ كَانَ مَكْسُورًا، فَوَزْنُهُ مِنَ: الْمُتَعَدِّي: عَالِمٌ، وَمِنَ اللَّازِمِ يَأْتِي عَلَى أَرْبَعَةِ أَوْزَانٍ:"]]},{"id":"ma7_3","label":"الْخَامِسُ: اسْمُ الْفَاعِلِ · ٣","segs":[["matn","مَرِيضٌ، وَزَمِنٌ بِفَتْحِ الزَّايِ وَكَسْرِ الْمِيمِ، وَأَحْمَرُ لِلْمُذَكَّرِ، وَحَمْرَاءُ لِلْمُؤَنَّثِ بِالْمَدِّ، وَجَمْعُهُمَا: حُمْرٌ بِضَمِّ الْحَاءِ وَسُكُونِ الْمِيمِ، وَتَثْنِيَةُ أَحْمَرَ: أَحْمَرَانِ، وَتَثْنِيَةُ حَمْرَاءَ: حَمْرَاوَانِ."]]},{"id":"ma7_4","label":"الْخَامِسُ: اسْمُ الْفَاعِلِ · ٤","segs":[["matn","وَعَطْشَانُ لِلْمُذَكَّرِ، وَتَثْنِيَةُ عَطْشَانَ: عَطْشَانَانِ، وَعَطْشَى بِفَتْحِ الْعَيْنِ وَسُكُونِ الطَّاءِ، وَبِالْقَصْرِ لِلْمُؤَنَّثِ؛ وَتَثْنِيَةُ عَطْشَى: عَطْشَيَانِ، وَجَمْعُهُمَا: عِطَاشٌ بِكَسْرِ الْعَيْنِ."]]},{"id":"ma7_5","label":"الْخَامِسُ: اسْمُ الْفَاعِلِ · ٥","segs":[["matn","وَاخْتَصَرْتُ بِذِكْرِ مَا يُمْكِنُ ضَبْطُهُ مِنَ الْفَاعِلِ، وَتَرَكْتُ مَا عَدَاهُ."]]}],"group":"فَصْلٌ فِي الْوُجُوهِ الَّتِي اشْتَدَّتِ الْحَاجَةُ إِلَى إِخْرَاجِهَا مِنَ الْمَصْدَرِ"},{"id":"ma8","title":"السَّادِسُ: اسْمُ الْمَفْعُولِ","units":[{"id":"ma8_1","label":"السَّادِسُ: اسْمُ الْمَفْعُولِ · ١","segs":[["matn","وَأَمَّا الْمَفْعُولُ مِنْ جَمِيعِ أَبْوَابِ الثُّلَاثِيِّ الْمُجَرَّدِ، فَوَزْنُهُ: مَجْبُورٌ، وَكَسِيرٌ، وَقَدْ ذَكَرْنَا الْفَاعِلَ وَالْمَفْعُولَ مِنَ الزَّوَائِدِ عَلَى الثُّلَاثِيِّ فِي الْمَصْدَرِ الْمِيمِيِّ."]]},{"id":"ma8_2","label":"السَّادِسُ: اسْمُ الْمَفْعُولِ · ٢","segs":[["matn","وَأَوْزَانُ الْمُبَالَغَةِ ثَمَانِيَةٌ: جَهُولٌ، وَصِدِّيقٌ، وَكَذَّابٌ، وَغُفُلٌ بِضَمِّ الْغَيْنِ وَالْفَاءِ، وَيَقُظٌ بِفَتْحِ الْيَاءِ وَضَمِّ الْقَافِ، وَمِدْرَارٌ، وَمِكْثِيرٌ."]]},{"id":"ma8_3","label":"السَّادِسُ: اسْمُ الْمَفْعُولِ · ٣","segs":[["matn","وَلُعَنَةٌ بِضَمِّ اللَّامِ وَفَتْحِ الْعَيْنِ، فَإِنْ أَسْكَنْتَ الْعَيْنَ مِنَ الْوَزْنِ الْأَخِيرِ يَصِيرُ بِمَعْنَى الْمَفْعُولِ."]]}],"group":"فَصْلٌ فِي الْوُجُوهِ الَّتِي اشْتَدَّتِ الْحَاجَةُ إِلَى إِخْرَاجِهَا مِنَ الْمَصْدَرِ"},{"id":"ma9","title":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ","units":[{"id":"ma9_1","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١","segs":[["matn","يَتَصَرَّفُ الْمَاضِي، وَالْمُسْتَقْبَلُ، وَالْأَمْرُ، وَالنَّهْيُ مِنَ الْمَعْرُوفِ وَالْمَجْهُولِ عَلَى أَرْبَعَةَ عَشَرَ وَجْهًا:"]]},{"id":"ma9_2","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢","segs":[["matn","ثَلَاثَةٌ لِلْغَائِبِ، وَثَلَاثَةٌ لِلْغَائِبَةِ، وَثَلَاثَةٌ لِلْمُخَاطَبِ، وَثَلَاثَةٌ لِلْمُخَاطَبَةِ، وَوَجْهَانِ لِلْمُتَكَلِّمِ، رَجُلًا كَانَ أَوِ امْرَأَةً، غَيْرَ أَنَّهُ لَا يَأْتِي الْوَجْهَانِ لِلْمُتَكَلِّمِ فِي الْمَعْرُوفِ مِنَ الْأَمْرِ وَالنَّهْيِ."]]},{"id":"ma9_3","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٣","segs":[["matn","وَالْفَاعِلُ: يَتَصَرَّفُ عَلَى عَشَرَةِ أَوْجُهٍ؛ مِنْهَا: جَمْعُ الْمُذَكَّرِ أَرْبَعَةُ أَلْفَاظٍ، وَجَمْعُ الْمُؤَنَّثِ لَفْظَانِ."]]},{"id":"ma9_4","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٤","segs":[["matn","وَالْمَفْعُولُ: يَتَصَرَّفُ عَلَى سَبْعَةِ أَوْجُهٍ؛ مِنْهَا: جَمْعُ الْمُذَكَّرِ لَفْظَانِ، وَجَمْعُ الْمُؤَنَّثِ لَفْظٌ وَاحِدٌ."]]},{"id":"ma9_5","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٥","segs":[["matn","وَنُونُ التَّأْكِيدِ الْمُشَدَّدَةُ: تَدْخُلُ عَلَى جَمِيعِ الْأَمْرِ وَالنَّهْيِ مِنَ الْمَعْرُوفِ وَالْمَجْهُولِ، وَالْمُخَفَّفَةُ كَذَلِكَ، غَيْرَ أَنَّهَا لَا تَدْخُلُ فِي التَّثْنِيَةِ، وَجَمْعِ الْمُؤَنَّثِ."]]},{"id":"ma9_6","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٦","segs":[["matn","وَالْمُخَفَّفَةُ سَاكِنَةٌ، وَالْمُشَدَّدَةُ مَفْتُوحَةٌ إِلَّا فِي التَّثْنِيَةِ، وَجَمْعِ الْمُؤَنَّثِ، فَإِنَّهَا مَكْسُورَةٌ فِيهِمَا، وَمَا قَبْلَهُمَا مَكْسُورٌ فِي الْوَاحِدَةِ الْحَاضِرَةِ، وَمَضْمُومٌ فِي جَمْعِ الْمُذَكَّرِ، وَمَفْتُوحٌ فِي الْبَوَاقِي."]]},{"id":"ma9_7","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٧","segs":[["matn","مِثَالُ الْمَاضِي: نَصَرَ، نَصَرَا، نَصَرُوا، إِلَخْ، وَمِنَ الْمَجْهُولِ: نُصِرَ، نُصِرَا، نُصِرُوا، إِلَخْ، وَمِثَالُ الْمُسْتَقْبَلِ: يَنْصُرُ، يَنْصُرَانِ، يَنْصُرُونَ، إِلَخْ، وَمِنَ الْمَجْهُولِ: يُنْصَرُ، يُنْصَرَانِ، يُنْصَرُونَ، إِلَخْ."]]},{"id":"ma9_8","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٨","segs":[["matn","وَمِثَالُ الْأَمْرِ الْغَائِبِ: لِيَنْصُرْ، لِيَنْصُرَا، لِيَنْصُرُوا، إِلَخْ، وَمِثَالُ الْأَمْرِ الْحَاضِرِ: انْصُرْ، انْصُرَا، انْصُرُوا، إِلَخْ، وَمِنَ الْمَجْهُولِ: لِتُنْصَرْ، لِتُنْصَرَا، لِتُنْصَرُوا، إِلَخْ."]]},{"id":"ma9_9","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٩","segs":[["matn","وَكَذَلِكَ النَّهْيُ فِي الْمَعْرُوفِ وَالْمَجْهُولِ، إِلَّا أَنَّهُ زِيدَ فِي أَوَّلِهِ لَا."]]},{"id":"ma9_10","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٠","segs":[["matn","وَتَقُولُ فِي نُونِ التَّأْكِيدِ الْمُشَدَّدَةِ: لِيَنْصُرَنَّ، لِيَنْصُرَانِّ، لِيَنْصُرُنَّ، لِتَنْصُرِنَّ، لِتَنْصُرَانِّ، لِتَنْصُرْنَانِّ، وَفِي الْأَمْرِ الْحَاضِرِ: انْصُرَنَّ، انْصُرَانِّ، انْصُرُنَّ، انْصُرِنَّ، انْصُرَانِّ، انْصُرْنَانِّ."]]},{"id":"ma9_11","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١١","segs":[["matn","وَبِالْمُخَفَّفَةِ: لِيَنْصُرَنْ بِفَتْحِ الرَّاءِ فِي الْوَاحِدِ الْمُذَكَّرِ، لِيَنْصُرُنْ بِضَمِّهَا فِي جَمْعِ الْمُذَكَّرِ، لِتَنْصُرَنْ بِفَتْحِ الرَّاءِ فِي الْوَاحِدَةِ الْغَائِبَةِ، وَفِي الْمُخَاطَبِ: انْصُرَنْ، انْصُرُنْ، انْصُرِنْ، وَكَذَلِكَ النَّهْيُ مِنَ الْمَعْرُوفِ وَالْمَجْهُولِ."]]},{"id":"ma9_12","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٢","segs":[["matn","وَمِثَالُ الْفَاعِلِ: نَاصِرٌ، نَاصِرَانِ، نَاصِرُونَ، نُصَّارٌ، وَنُصَّرٌ بِضَمِّ النُّونِ، وَفَتْحِ الصَّادِ، وَالتَّشْدِيدِ فِيهِمَا، وَنَصَرَةٌ بِفَتْحِ النُّونِ وَالصَّادِ وَالرَّاءِ، مَعَ التَّخْفِيفِ، نَاصِرَةٌ، نَاصِرَتَانِ، نَاصِرَاتٌ، وَنَوَاصِرُ."]]},{"id":"ma9_13","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٣","segs":[["matn","وَمِثَالُ الْمَفْعُولِ: مَنْصُورٌ، مَنْصُورَانِ، مَنْصُورُونَ، بِفَتْحِ الْمِيمِ، مَنْصُورَةٌ، مَنْصُورَتَانِ، مَنْصُورَاتٌ، وَمَنَاصِرُ."]]},{"id":"ma9_14","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٤","segs":[["matn","مِثَالُ الرُّبَاعِيِّ الْمُجَرَّدِ: دَحْرَجَ، يُدَحْرِجُ بِضَمِّ الْيَاءِ، وَكَسْرِ الرَّاءِ، وَسُكُونِ الْحَاءِ، دَحْرَجَةً بِفَتْحِ الدَّالِ، وَسُكُونِ الْحَاءِ، وَدِحْرَاجًا بِكَسْرِ الدَّالِ، وَسُكُونِ الْحَاءِ، فَهُوَ مُدَحْرِجٌ، وَذَاكَ مُدَحْرَجٌ."]]},{"id":"ma9_15","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٥","segs":[["matn","وَالْأَمْرُ: دَحْرِجْ بِفَتْحِ الدَّالِ، وَكَسْرِ الرَّاءِ، وَالنَّهْيُ: لَا تُدَحْرِجْ بِضَمِّ التَّاءِ، وَكَسْرِ الرَّاءِ، وَكَذَلِكَ تَصْرِيفُ الْمُلْحَقَاتِ."]]},{"id":"ma9_16","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٦","segs":[["matn","وَمِثَالُ الثُّلَاثِيِّ الْمَزِيدِ فِيهِ: أَخْرَجَ، يُخْرِجُ، إِخْرَاجًا، فَهُوَ مُخْرِجٌ، وَذَاكَ مُخْرَجٌ، وَالْأَمْرُ: أَخْرِجْ، وَالنَّهْيُ: لَا تُخْرِجْ بِضَمِّ التَّاءِ، وَكَسْرِ الرَّاءِ فِيهِمَا."]]},{"id":"ma9_17","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٧","segs":[["matn","وَقَدْ حُذِفَتِ الْهَمْزَةُ مِنْ مُسْتَقْبَلِ هَذَا الْبَابِ، لِئَلَّا يَجْتَمِعَ هَمْزَتَانِ فِي نَفْسِ الْمُتَكَلِّمِ، وَكَذَا حُذِفَتْ مِنَ الْفَاعِلِ، وَالْمَفْعُولِ، وَأَمْرِ الْغَائِبِ، وَالنَّهْيِ؛ طَرْدًا لِلْبَابِ."]]},{"id":"ma9_18","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٨","segs":[["matn","وَخَرَّجَ، يُخَرِّجُ، تَخْرِيجًا، وَتَخْرِجَةً بِكَسْرِ الرَّاءِ، وَفَتْحِ التَّاءِ فِيهِمَا، فَهُوَ مُخَرِّجٌ، وَذَاكَ مُخَرَّجٌ، وَالْأَمْرُ: خَرِّجْ، وَالنَّهْيُ: لَا تُخَرِّجْ بِضَمِّ التَّاءِ، وَكَسْرِ الرَّاءِ فِيهِمَا."]]},{"id":"ma9_19","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ١٩","segs":[["matn","وَخَاصَمَ، يُخَاصِمُ بِكَسْرِ الصَّادِ، مُخَاصَمَةً بِفَتْحِ الصَّادِ، وَخِصَامًا بِكَسْرِ الْخَاءِ، فَهُوَ مُخَاصِمٌ، وَذَاكَ مُخَاصَمٌ، وَالْأَمْرُ: خَاصِمْ، وَالنَّهْيُ: لَا تُخَاصِمْ، وَمَجْهُولُ الْمَاضِي: خُوصِمَ، وَمَجْهُولُ الْمُضَارِعِ: يُخَاصَمُ بِفَتْحِ الصَّادِ."]]},{"id":"ma9_20","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٠","segs":[["matn","مِثَالُ الْخُمَاسِيِّ: انْكَسَرَ، يَنْكَسِرُ بِكَسْرِ السِّينِ، انْكِسَارًا، فَهُوَ مُنْكَسِرٌ، وَذَاكَ مُنْكَسَرٌ، وَالْأَمْرُ: انْكَسِرْ، وَالنَّهْيُ: لَا تَنْكَسِرْ بِكَسْرِ السِّينِ فِيهِمَا."]]},{"id":"ma9_21","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢١","segs":[["matn","وَاكْتَسَبَ، يَكْتَسِبُ، اكْتِسَابًا، فَهُوَ مُكْتَسِبٌ، وَذَاكَ مُكْتَسَبٌ، وَالْأَمْرُ: اكْتَسِبْ، وَالنَّهْيُ: لَا تَكْتَسِبْ بِكَسْرِ السِّينِ فِيهِمَا."]]},{"id":"ma9_22","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٢","segs":[["matn","وَاصْفَرَّ، يَصْفَرُّ بِفَتْحِ الْفَاءِ فِيهِمَا، اصْفِرَارًا، فَهُوَ مُصْفَرٌّ بِفَتْحِ الْفَاءِ، وَذَاكَ مُصْفَرٌّ بِهِ، وَالْأَمْرُ: اصْفَرَّ، وَالنَّهْيُ: لَا تَصْفَرَّ بِفَتْحِ الْفَاءِ فِيهِمَا."]]},{"id":"ma9_23","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٣","segs":[["matn","وَتَكَسَّرَ، يَتَكَسَّرُ بِفَتْحِ السِّينِ فِيهِمَا، تَكَسُّرًا بِضَمِّ السِّينِ، فَهُوَ مُتَكَسِّرٌ بِكَسْرِ السِّينِ، وَذَاكَ مُتَكَسَّرٌ بِهِ بِفَتْحِ السِّينِ، وَالْأَمْرُ: تَكَسَّرْ، وَالنَّهْيُ: لَا تَتَكَسَّرْ بِفَتْحِ السِّينِ فِيهِمَا."]]},{"id":"ma9_24","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٤","segs":[["matn","وَتَصَالَحَ، يَتَصَالَحُ بِفَتْحِ اللَّامِ، تَصَالُحًا بِضَمِّ اللَّامِ، فَهُوَ مُتَصَالِحٌ بِكَسْرِ اللَّامِ، وَذَاكَ مُتَصَالَحٌ بِفَتْحِ اللَّامِ، وَالْأَمْرُ: تَصَالَحْ، وَالنَّهْيُ: لَا تَتَصَالَحْ بِفَتْحِ اللَّامِ فِيهِمَا."]]},{"id":"ma9_25","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٥","segs":[["matn","وَأَمَّا ادَّثَّرَ، وَاثَّاقَلَ، فَأَصْلُ الْأَوَّلِ: تَدَثَّرَ كَتَكَسَّرَ، وَأَصْلُ الثَّانِي: تَثَاقَلَ كَتَصَالَحَ، فَأُدْغِمَتِ التَّاءُ فِيمَا بَعْدَهُمَا، ثُمَّ أُدْخِلَتْ هَمْزَةُ الْوَصْلِ لِيُمْكِنَ الِابْتِدَاءُ بِهَا؛ لِأَنَّ السَّاكِنَ لَا يُبْتَدَأُ بِهِ."]]},{"id":"ma9_26","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٦","segs":[["matn","وَتَصْرِيفُهُ: ادَّثَّرَ، يَدَّثَّرُ بِفَتْحِ الثَّاءِ فِيهِمَا، ادَّثُّرًا بِضَمِّ الثَّاءِ، فَهُوَ مُدَّثِّرٌ بِكَسْرِ الثَّاءِ، وَذَاكَ مُدَّثَّرٌ عَلَيْهِ، وَالْأَمْرُ: ادَّثَّرْ، وَالنَّهْيُ: لَا تَدَّثَّرْ بِفَتْحِ الثَّاءِ فِيهِمَا، وَبِفَتْحِ الدَّالِ وَالتَّشْدِيدِ فِي الْجَمِيعِ."]]},{"id":"ma9_27","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٧","segs":[["matn","وَاثَّاقَلَ، يَثَّاقَلُ بِفَتْحِ الْقَافِ، اثَّاقُلًا بِضَمِّ الْقَافِ، فَهُوَ مُثَّاقِلٌ بِكَسْرِ الْقَافِ، وَذَاكَ مُثَّاقَلٌ عَلَيْهِ بِفَتْحِ الْقَافِ، وَالْأَمْرُ: اثَّاقَلْ، وَالنَّهْيُ: لَا تَثَّاقَلْ بِفَتْحِ الْقَافِ فِيهِمَا، وَالثَّاءُ مُشَدَّدَةٌ فِي الْجَمِيعِ."]]},{"id":"ma9_28","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٨","segs":[["matn","وَتَدَحْرَجَ، يَتَدَحْرَجُ بِفَتْحِ الرَّاءِ فِيهِمَا، تَدَحْرُجًا بِضَمِّ الرَّاءِ، فَهُوَ مُتَدَحْرِجٌ بِكَسْرِ الرَّاءِ، وَذَاكَ مُتَدَحْرَجٌ بِهِ بِفَتْحِ الرَّاءِ، وَالْأَمْرُ: تَدَحْرَجْ، وَالنَّهْيُ: لَا تَتَدَحْرَجْ بِفَتْحِ الرَّاءِ فِيهِمَا."]]},{"id":"ma9_29","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٢٩","segs":[["matn","مِثَالُ السُّدَاسِيِّ: اسْتَغْفَرَ، يَسْتَغْفِرُ بِكَسْرِ الْفَاءِ، اسْتِغْفَارًا، فَهُوَ مُسْتَغْفِرٌ بِكَسْرِ الْفَاءِ، وَذَاكَ مُسْتَغْفَرٌ بِفَتْحِ الْفَاءِ، وَالْأَمْرُ: اسْتَغْفِرْ، وَالنَّهْيُ: لَا تَسْتَغْفِرْ بِكَسْرِ الْفَاءِ فِيهِمَا."]]},{"id":"ma9_30","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٣٠","segs":[["matn","وَاشْهَابَّ، يَشْهَابُّ، اشْهِيبَابًا، فَهُوَ مُشْهَابٌّ، وَذَاكَ مُشْهَابٌّ بِهِ، وَالْأَمْرُ: اشْهَابَّ، وَالنَّهْيُ: لَا تَشْهَابَّ بِتَشْدِيدِ الْبَاءِ فِي الْجَمِيعِ إِلَّا فِي الْمَصْدَرِ."]]},{"id":"ma9_31","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٣١","segs":[["matn","وَاغْدَوْدَنَ، يَغْدَوْدِنُ بِكَسْرِ الدَّالِ الثَّانِيَةِ، اغْدِيدَانًا، فَهُوَ مُغْدَوْدِنٌ، وَذَاكَ مُغْدَوْدَنٌ عَلَيْهِ، وَالْأَمْرُ: اغْدَوْدِنْ، وَالنَّهْيُ: لَا تَغْدَوْدِنْ بِكَسْرِ الدَّالِ الثَّانِيَةِ فِي الثَّلَاثِ."]]},{"id":"ma9_32","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٣٢","segs":[["matn","وَاجْلَوَّذَ، يَجْلَوِّذُ بِكَسْرِ الْوَاوِ، اجْلِوَّاذًا بِكَسْرِ اللَّامِ، فَهُوَ مُجْلَوِّذٌ، وَذَاكَ مُجْلَوَّذٌ عَلَيْهِ، وَالْأَمْرُ: اجْلَوِّذْ، وَالنَّهْيُ: لَا تَجْلَوِّذْ بِكَسْرِ الْوَاوِ فِي الثَّلَاثِ، وَالْوَاوُ مُشَدَّدَةٌ فِي الْجَمِيعِ."]]},{"id":"ma9_33","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٣٣","segs":[["matn","وَاسْحَنْكَكَ، يَسْحَنْكِكُ بِكَسْرِ الْكَافِ الْأُولَى، اسْحِنْكَاكًا، فَهُوَ مُسْحَنْكِكٌ، وَذَاكَ مُسْحَنْكَكٌ بِهِ، وَالْأَمْرُ: اسْحَنْكِكْ، وَالنَّهْيُ: لَا تَسْحَنْكِكْ بِكَسْرِ الْكَافِ فِي الثَّلَاثِ."]]},{"id":"ma9_34","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٣٤","segs":[["matn","وَاسْلَنْقَى، يَسْلَنْقِي، اسْلِنْقَاءً، فَهُوَ مُسْلَنْقٍ، وَذَاكَ مُسْلَنْقًى عَلَيْهِ، وَالْأَمْرُ: اسْلَنْقِ، وَالنَّهْيُ: لَا تَسْلَنْقِ بِكَسْرِ الْقَافِ فِيهِمَا."]]},{"id":"ma9_35","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٣٥","segs":[["matn","وَاقْشَعَرَّ، يَقْشَعِرُّ بِكَسْرِ الْعَيْنِ، اقْشِعْرَارًا بِسُكُونِ الْعَيْنِ، فَهُوَ مُقْشَعِرٌّ، وَذَاكَ مُقْشَعَرٌّ بِهِ، وَالْأَمْرُ: اقْشَعِرَّ، وَالنَّهْيُ: لَا تَقْشَعِرَّ بِكَسْرِ الْعَيْنِ فِي الثَّلَاثِ، وَالرَّاءُ مُشَدَّدَةٌ فِي الْجَمِيعِ إِلَّا فِي الْمَصْدَرِ."]]},{"id":"ma9_36","label":"فَصْلٌ فِي تَصْرِيفِ الْأَفْعَالِ الصَّحِيحَةِ · ٣٦","segs":[["matn","وَاحْرَنْجَمَ، يَحْرَنْجِمُ بِكَسْرِ الْجِيمِ، احْرِنْجَامًا، فَهُوَ مُحْرَنْجِمٌ، وَذَاكَ مُحْرَنْجَمٌ بِهِ، وَالْأَمْرُ: احْرَنْجِمْ، وَالنَّهْيُ: لَا تَحْرَنْجِمْ بِكَسْرِ الْجِيمِ فِي الثَّلَاثِ."]]}]},{"id":"ma10","title":"فَصْلٌ فِي الْفَوَائِدِ","units":[{"id":"ma10_1","label":"فَصْلٌ فِي الْفَوَائِدِ · ١","segs":[["matn","اللَّازِمُ: يَصِيرُ مُتَعَدِّيًا بِأَحَدِ ثَلَاثَةِ أَسْبَابٍ: بِزِيَادَةِ الْهَمْزَةِ فِي أَوَّلِهِ، وَحَرْفِ الْجَرِّ فِي آخِرِهِ، وَتَشْدِيدِ عَيْنِهِ، نَحْوُ: أَخْرَجْتُهُ، وَخَرَجْتُ بِهِ مِنَ الدَّارِ، وَخَرَّجْتُهُ."]]},{"id":"ma10_2","label":"فَصْلٌ فِي الْفَوَائِدِ · ٢","segs":[["matn","وَبِحَذْفِ التَّاءِ مِنْ تَفَعَّلَ وَتَفَعْلَلَ مُشَدَّدَةَ الْعَيْنِ، وَمُكَرَّرَةَ اللَّامِ."]]},{"id":"ma10_3","label":"فَصْلٌ فِي الْفَوَائِدِ · ٣","segs":[["matn","وَالْمُتَعَدِّي: يَصِيرُ لَازِمًا بِحَذْفِ أَسْبَابِ التَّعْدِيَةِ، أَوْ بِنَقْلِهِ إِلَى بَابِ انْكَسَرَ، وَبَابُ فَعْلَلَ يَصِيرُ لَازِمًا بِزِيَادَةِ التَّاءِ فِي أَوَّلِهِ."]]},{"id":"ma10_4","label":"فَصْلٌ فِي الْفَوَائِدِ · ٤","segs":[["matn","وَلَا يَجِيءُ الْمَفْعُولُ بِهِ وَالْمَجْهُولُ مِنَ اللَّازِمِ؛ لِأَنَّ اللَّازِمَ مِنَ الْأَفْعَالِ هُوَ مَا لَا يَحْتَاجُ إِلَى الْمَفْعُولِ بِهِ، وَالْمُتَعَدِّي بِخِلَافِهِ."]]},{"id":"ma10_5","label":"فَصْلٌ فِي الْفَوَائِدِ · ٥","segs":[["matn","وَبَابُ فَاعَلَ يَكُونُ لِلْمُشَارَكَةِ بَيْنَ الِاثْنَيْنِ، نَحْوُ: نَاضَلْتُهُ، إِلَّا قَلِيلًا، نَحْوُ: طَارَقْتُ النَّعْلَ، وَعَاقَبْتُ اللِّصَّ."]]},{"id":"ma10_6","label":"فَصْلٌ فِي الْفَوَائِدِ · ٦","segs":[["matn","وَبَابُ تَفَاعَلَ أَيْضًا يَكُونُ بَيْنَ الِاثْنَيْنِ فَصَاعِدًا، نَحْوُ: تَدَافَعْنَا، وَتَصَالَحَ الْقَوْمُ، وَقَدْ يَكُونُ لِإِظْهَارِ مَا لَيْسَ فِي الْبَاطِنِ، نَحْوُ: تَمَارَضْتُ أَيْ: أَظْهَرْتُ الْمَرَضَ، وَلَيْسَ بِي مَرَضٌ."]]},{"id":"ma10_7","label":"فَصْلٌ فِي الْفَوَائِدِ · ٧","segs":[["matn","وَإِذَا كَانَ فَاءُ الْفِعْلِ مِنْ بَابِ افْتَعَلَ حَرْفًا مِنْ حُرُوفِ الْإِطْبَاقِ، وَهِيَ: الصَّادُ، وَالضَّادُ، وَالطَّاءُ، وَالظَّاءُ، يَصِيرُ تَاءُ افْتَعَلَ طَاءً، نَحْوُ: اصْطَبَرَ، وَاضْطَرَبَ، وَاطَّرَدَ، وَاظَّهَرَ."]]},{"id":"ma10_8","label":"فَصْلٌ فِي الْفَوَائِدِ · ٨","segs":[["matn","وَإِذَا كَانَ فَاءُ افْتَعَلَ دَالًا، أَوْ ذَالًا، أَوْ زَايًا، يَصِيرُ تَاءُ افْتَعَلَ دَالًا، نَحْوُ: ادَّمَعَ وَاذَّكَرَ بِإِدْغَامِ الدَّالِ فِي الذَّالِ، وَازْدَجَرَ."]]},{"id":"ma10_9","label":"فَصْلٌ فِي الْفَوَائِدِ · ٩","segs":[["matn","وَإِذَا كَانَ فَاؤُهُ وَاوًا، أَوْ يَاءً، أَوْ ثَاءً؛ قُلِبَتِ الْوَاوُ وَالْيَاءُ وَالثَّاءُ تَاءً، ثُمَّ أُدْغِمَتِ التَّاءُ فِي تَاءِ افْتَعَلَ، نَحْوُ: اتَّقَى، وَاتَّسَرَ، وَاتَّغَرَ."]]},{"id":"ma10_10","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٠","segs":[["matn","وَالْحُرُوفُ الَّتِي تُزَادُ فِي الْأَسْمَاءِ وَالْأَفْعَالِ عَشَرَةٌ، مَجْمُوعُهَا: الْيَوْمَ تَنْسَاهُ، فَإِذَا كَانَتْ كَلِمَةٌ، وَعَدَدُهَا زَائِدٌ عَلَى ثَلَاثَةِ أَحْرُفٍ، وَفِيهَا حَرْفٌ وَاحِدٌ مِنْ هَذِهِ الْحُرُوفِ؛ فَاحْكُمْ بِأَنَّهَا زَائِدَةٌ، إِلَّا أَنْ لَا يَكُونَ لَهَا مَعْنًى بِدُونِهَا، نَحْوُ: وَسْوَسَ."]]},{"id":"ma10_11","label":"فَصْلٌ فِي الْفَوَائِدِ · ١١","segs":[["matn","وَأَبْوَابُ الرُّبَاعِيِّ كُلُّهَا مُتَعَدٍّ إِلَّا: دَرْبَخَ، وَأَبْوَابُ الْخُمَاسِيِّ كُلُّهَا لَوَازِمُ، إِلَّا ثَلَاثَةَ أَبْوَابٍ: افْتَعَلَ، وَتَفَعَّلَ، وَتَفَاعَلَ، فَإِنَّهَا مُشْتَرَكَةٌ بَيْنَ اللَّازِمِ وَالْمُتَعَدِّي."]]},{"id":"ma10_12","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٢","segs":[["matn","وَأَبْوَابُ السُّدَاسِيِّ كُلُّهَا لَوَازِمُ، إِلَّا بَابَ اسْتَفْعَلَ، فَإِنَّهُ مُشْتَرَكٌ بَيْنَ اللَّازِمِ وَالْمُتَعَدِّي، وَكَلِمَتَيْنِ مِنْ بَابِ افْعَنْلَى، فَإِنَّهُمَا مُتَعَدِّيَانِ، وَهُمَا: اسْرَنْدَاهُ، وَاغْرَنْدَاهُ، مَعْنَاهُمَا: غَلَبَ عَلَيْهِ، وَقَهَرَهُ."]]},{"id":"ma10_13","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٣","segs":[["matn","وَهَمْزَةُ أَفْعَلَ تَجِيءُ لِمَعَانٍ: لِلتَّعْدِيَةِ، نَحْوُ: أَكْرَمْتُهُ، وَلِلصَّيْرُورَةِ، نَحْوُ: أَمْشَى الرَّجُلُ، أَيْ: صَارَ ذَا مَاشِيَةٍ، وَلِلْوِجْدَانِ، نَحْوُ: أَبْخَلْتُهُ، أَيْ: وَجَدْتُهُ بَخِيلًا."]]},{"id":"ma10_14","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٤","segs":[["matn","وَلِلْحَيْنُونَةِ، نَحْوُ: أَحْصَدَ الزَّرْعُ، أَيْ: حَانَ وَقْتُ حَصَادِهِ، وَلِلْإِزَالَةِ، نَحْوُ: أَشْكَيْتُهُ، أَيْ: أَزَلْتُ عَنْهُ الشِّكَايَةَ."]]},{"id":"ma10_15","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٥","segs":[["matn","وَلِلدُّخُولِ فِي الشَّيْءِ، نَحْوُ: أَصْبَحَ الرَّجُلُ أَيْ: دَخَلَ فِي الصَّبَاحِ، وَلِلْكَثْرَةِ، نَحْوُ: أَلْبَنَ الرَّجُلُ: إِذَا كَثُرَ عِنْدَهُ اللَّبَنُ."]]},{"id":"ma10_16","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٦","segs":[["matn","وَلِلتَّعْرِيضِ، نَحْوُ: أَبَاعَ الْجَارِيَةَ، أَيْ: عَرَضَهَا لِلْبَيْعِ، وَلِلتَّمَكُّنِ، نَحْوُ: أَقْرَبْتُهُ، أَيْ: جَعَلْتُهُ قَرِيبًا."]]},{"id":"ma10_17","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٧","segs":[["matn","وَسِينُ اسْتَفْعَلَ أَيْضًا يَجِيءُ لِمَعَانٍ: لِلطَّلَبِ، نَحْوُ: أَسْتَغْفِرُ اللَّهَ، أَيْ: أَطْلُبُ مِنْهُ الْمَغْفِرَةَ، وَلِلسُّؤَالِ، نَحْوُ: اسْتَخْبَرَ أَيْ: سَأَلَ الْخَبَرَ."]]},{"id":"ma10_18","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٨","segs":[["matn","وَلِلتَّحَوُّلِ، نَحْوُ: اسْتَخَلَّ الْخَمْرُ خَلًّا، أَيْ: انْقَلَبَ الْخَمْرُ خَلًّا، وَلِلِاعْتِقَادِ، نَحْوُ: اسْتَكْرَمْتُهُ، أَيْ: اعْتَقَدْتُ أَنَّهُ كَرِيمٌ."]]},{"id":"ma10_19","label":"فَصْلٌ فِي الْفَوَائِدِ · ١٩","segs":[["matn","وَلِلْوِجْدَانِ، نَحْوُ: اسْتَجَدْتُ شَيْئًا، أَيْ: وَجَدْتُهُ جَيِّدًا، وَلِلتَّسْلِيمِ، نَحْوُ قَوْلِهِمْ: اسْتَرْجَعَ الْقَوْمُ عِنْدَ الْمُصِيبَةِ، أَيْ: قَالُوا: إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ."]]},{"id":"ma10_20","label":"فَصْلٌ فِي الْفَوَائِدِ · ٢٠","segs":[["matn","وَحُرُوفُ الْمَدِّ، وَاللِّينِ، وَالزَّوَائِدِ، وَالْعِلَّةِ وَاحِدَةٌ، وَهِيَ: الْوَاوُ، وَالْيَاءُ، وَالْأَلِفُ."]]},{"id":"ma10_21","label":"فَصْلٌ فِي الْفَوَائِدِ · ٢١","segs":[["matn","وَكُلُّ فِعْلٍ مَاضٍ فِي أَوَّلِهِ حَرْفٌ مِنْ هَذِهِ الْحُرُوفِ يُسَمَّى: مُعْتَلًّا، وَمِثَالًا؛ لِمُمَاثَلَتِهِ الصَّحِيحَ فِي احْتِمَالِ الْحَرَكَاتِ، نَحْوُ: وَعَدَ، وَيَقِظَ."]]},{"id":"ma10_22","label":"فَصْلٌ فِي الْفَوَائِدِ · ٢٢","segs":[["matn","وَإِذَا كَانَ فِي وَسَطِهِ يُسَمَّى: أَجْوَفَ، نَحْوُ: قَالَ، وَكَالَ، وَإِذَا كَانَ فِي آخِرِهِ يُسَمَّى: نَاقِصًا، نَحْوُ: غَزَا، وَرَمَى."]]},{"id":"ma10_23","label":"فَصْلٌ فِي الْفَوَائِدِ · ٢٣","segs":[["matn","وَإِذَا كَانَ فِيهِ حَرْفَانِ مِنْ هَذِهِ الْحُرُوفِ؛ فَإِنْ كَانَ فِي عَيْنِهِ وَلَامِهِ يُسَمَّى: اللَّفِيفَ الْمَقْرُونَ، نَحْوُ: شَوَى وَطَوَى، وَإِنْ كَانَ فَاءَهُ وَلَامَهُ يُسَمَّى: اللَّفِيفَ الْمَفْرُوقَ، نَحْوُ: وَقَى، يَقِي."]]},{"id":"ma10_24","label":"فَصْلٌ فِي الْفَوَائِدِ · ٢٤","segs":[["matn","وَكُلُّ فِعْلٍ يَكُونُ عَيْنُهُ وَلَامُهُ حَرْفَانِ مِنْ جِنْسٍ وَاحِدٍ؛ أُدْغِمَ أَوَّلُهُمَا فِي الْآخِرِ دَفْعًا لِلثِّقَلِ يُسَمَّى: مُضَاعَفًا، نَحْوُ: مَدَّ."]]},{"id":"ma10_25","label":"فَصْلٌ فِي الْفَوَائِدِ · ٢٥","segs":[["matn","وَكُلُّ فِعْلٍ فِيهِ هَمْزَةٌ: فَإِنْ كَانَتْ فِي أَوَّلِهِ يُسَمَّى: مَهْمُوزَ الْفَاءِ، نَحْوُ: أَخَذَ، وَإِنْ كَانَتْ فِي وَسَطِهِ يُسَمَّى: مَهْمُوزَ الْعَيْنِ، نَحْوُ: سَأَلَ، وَإِنْ كَانَتْ فِي آخِرِهِ يُسَمَّى: مَهْمُوزَ اللَّامِ، نَحْوُ: قَرَأَ."]]},{"id":"ma10_26","label":"فَصْلٌ فِي الْفَوَائِدِ · ٢٦","segs":[["matn","وَكُلُّ فِعْلٍ خَالٍ مِنْ هَذِهِ الْأَقْسَامِ السِّتَّةِ يُسَمَّى: صَحِيحًا، وَقَدْ مَرَّ بَحْثُ بَابِ الصَّحِيحِ، وَسَنَذْكُرُ بَحْثَ الْأَقْسَامِ السِّتَّةِ عَلَى سَبِيلِ الِاخْتِصَارِ إِنْ شَاءَ اللَّهُ."]]}]},{"id":"ma11","title":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ","units":[{"id":"ma11_1","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١","segs":[["matn","الْوَاوُ وَالْيَاءُ إِذَا تَحَرَّكَتَا، وَانْفَتَحَ مَا قَبْلَهُمَا قُلِبَتَا أَلِفًا، نَحْوُ: قَالَ، وَكَالَ، وَمِثَالُهُمَا مِنَ النَّاقِصِ: غَزَا، وَرَمَى."]]},{"id":"ma11_2","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢","segs":[["matn","وَتَقُولُ فِي تَثْنِيَتِهِمَا: غَزَوَا، وَرَمَيَا، فَلَا تُقْلَبَانِ أَلِفًا، وَلَا تُقْلَبَانِ أَيْضًا فِي جَمْعِ الْمُؤَنَّثِ، وَالْمُوَاجَهَةِ، وَنَفْسِ الْمُتَكَلِّمِ."]]},{"id":"ma11_3","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣","segs":[["matn","لِأَنَّ الْوَاوَ السَّاكِنَةَ وَالْيَاءَ السَّاكِنَةَ لَا تُقْلَبَانِ أَلِفًا إِلَّا فِي مَوْضِعٍ يَكُونُ فِيهِ سُكُونُهُمَا غَيْرَ أَصْلِيٍّ؛ بِأَنْ نُقِلَتْ حَرَكَتُهُمَا إِلَى مَا قَبْلَهُمَا، نَحْوُ: أَقَامَ، وَأَبَاعَ."]]},{"id":"ma11_4","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤","segs":[["matn","وَتَقُولُ فِي الْجَمْعِ الْمُذَكَّرِ: غَزَوْا، وَرَمَوْا، وَالْأَصْلُ: غَزَوُوا، وَرَمَيُوا؛ قُلِبَتَا أَلِفًا لِتَحَرُّكِهِمَا وَانْفِتَاحِ مَا قَبْلَهُمَا، فَاجْتَمَعَ سَاكِنَانِ: أَحَدُهُمَا الْأَلِفُ الْمَقْلُوبَةُ، وَالثَّانِي وَاوُ الْجَمْعِ، فَحُذِفَتِ الْأَلِفُ الْمَقْلُوبَةُ، فَبَقِيَ: غَزَوْا وَرَمَوْا."]]},{"id":"ma11_5","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥","segs":[["matn","وَتَقُولُ فِي الْمُفْرَدَةِ الْمُؤَنَّثَةِ الْغَائِبَةِ: غَزَتْ، وَرَمَتْ، وَالْأَصْلُ: غَزَوَتْ، وَرَمَيَتْ؛ قُلِبَتِ الْوَاوُ وَالْيَاءُ أَلِفًا لِتَحَرُّكِهِمَا وَانْفِتَاحِ مَا قَبْلَهُمَا، فَاجْتَمَعَ سَاكِنَانِ؛ أَحَدُهُمَا الْأَلِفُ الْمَقْلُوبَةُ، وَالثَّانِي التَّاءُ، فَحُذِفَتِ الْأَلِفُ الْمَقْلُوبَةُ لِسُكُونِهَا وَسُكُونِ التَّاءِ، فَبَقِيَ: غَزَتْ وَرَمَتْ."]]},{"id":"ma11_6","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٦","segs":[["matn","وَتَقُولُ فِي تَثْنِيَتِهِمَا مِنَ الْمُؤَنَّثِ: غَزَتَا، وَرَمَتَا، وَالْأَصْلُ: غَزَوَتَا وَرَمَيَتَا؛ فَقُلِبَتِ الْوَاوُ وَالْيَاءُ أَلِفًا لِتَحَرُّكِهِمَا وَانْفِتَاحِ مَا قَبْلَهُمَا، وَحُذِفَتِ الْأَلِفُ الْمَقْلُوبَةُ لِسُكُونِهَا، وَسُكُونِ التَّاءِ."]]},{"id":"ma11_7","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٧","segs":[["matn","لِأَنَّ التَّاءَ كَانَتْ سَاكِنَةً فِي الْأَصْلِ، فَحُرِّكَتِ التَّاءُ لِأَلِفِ التَّثْنِيَةِ، فَحَرَكَتُهَا عَارِضَةٌ، وَالْعَارِضُ كَالْمَعْدُومِ."]]},{"id":"ma11_8","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٨","segs":[["matn","وَتَقُولُ فِي جَمْعِ الْمُؤَنَّثِ مِنَ الْأَجْوَفِ: قُلْنَ، وَكِلْنَ، وَالْأَصْلُ: قَوَلْنَ، وَكَيَلْنَ، قُلِبَتَا أَلِفًا لِتَحَرُّكِهِمَا وَانْفِتَاحِ مَا قَبْلَهُمَا، ثُمَّ حُذِفَتِ الْأَلِفُ الْمَقْلُوبَةُ لِسُكُونِهَا وَسُكُونِ اللَّامِ، فَبَقِيَ: قَلْنَ، وَكَلْنَ، بِفَتْحِ الْقَافِ وَالْكَافِ."]]},{"id":"ma11_9","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٩","segs":[["matn","ثُمَّ نُقِلَتْ فَتْحَةُ الْقَافِ إِلَى الضَّمَّةِ، وَالْكَافِ إِلَى الْكَسْرَةِ؛ لِتَدُلَّ الضَّمَّةُ عَلَى الْوَاوِ الْمَحْذُوفَةِ، وَالْكَسْرَةُ عَلَى الْيَاءِ الْمَحْذُوفَةِ؛ لِأَنَّ الْمُتَوَلِّدَ مِنَ الضَّمَّةِ الْوَاوُ، وَمِنَ الْكَسْرَةِ الْيَاءُ، وَمِنَ الْفَتْحَةِ الْأَلِفُ."]]},{"id":"ma11_10","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٠","segs":[["matn","وَالْيَاءُ إِذَا انْكَسَرَ مَا قَبْلَهَا، تُرِكَتْ عَلَى حَالِهَا سَاكِنَةً كَانَتْ أَوْ مُتَحَرِّكَةً؛ إِذَا كَانَتِ الْحَرَكَةُ فَتْحَةً، نَحْوُ: خَشِيَ، وَخَشِيتُ."]]},{"id":"ma11_11","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١١","segs":[["matn","وَالْيَاءُ السَّاكِنَةُ إِذَا انْضَمَّ مَا قَبْلَهَا قُلِبَتْ وَاوًا، نَحْوُ: أَيْسَرَ، يُوسِرُ، وَالْأَصْلُ: يُيْسِرُ."]]},{"id":"ma11_12","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٢","segs":[["matn","وَتَقُولُ فِي مَجْهُولِ الْأَجْوَفِ: قِيلَ، وَالْأَصْلُ: قُوِلَ، فَاسْتُثْقِلَتْ ضَمَّةُ الْقَافِ قَبْلَ كَسْرَةِ الْوَاوِ؛ فَحُذِفَتْ ضَمَّةُ الْقَافِ، فَأُسْكِنَتِ الْقَافُ، وَنُقِلَتْ كَسْرَةُ الْوَاوِ إِلَيْهَا."]]},{"id":"ma11_13","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٣","segs":[["matn","فَصَارَتِ الْقَافُ مَكْسُورَةً، وَالْوَاوُ سَاكِنَةً، ثُمَّ قُلِبَتِ الْوَاوُ يَاءً؛ لِأَنَّ الْوَاوَ السَّاكِنَةَ إِذَا انْكَسَرَ مَا قَبْلَهَا قُلِبَتْ يَاءً."]]},{"id":"ma11_14","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٤","segs":[["matn","وَالْوَاوُ الْمُتَحَرِّكَةُ إِذَا وَقَعَتْ فِي آخِرِ الْكَلِمَةِ، وَانْكَسَرَ مَا قَبْلَهَا؛ قُلِبَتْ يَاءً، نَحْوُ: غَبِيَ، وَالْأَصْلُ: غَبِوَ، مِنَ الْغَبَاوَةِ، وَالْغَبَاوَةُ: عَكْسُ الْإِدْرَاكِ، وَكَذَا دُعِيَ مَجْهُولُ دَعَا، وَالْأَصْلُ: دُعِوَ."]]},{"id":"ma11_15","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٥","segs":[["matn","وَتَقُولُ فِي جَمْعِ الْمُذَكَّرِ مِنْ مَجْهُولِ النَّاقِصِ: غُزُوا، وَالْأَصْلُ: غُزِيُوا؛ فَأُسْكِنَتِ الزَّايُ، ثُمَّ نُقِلَتْ ضَمَّةُ الْيَاءِ إِلَى الزَّايِ، وَحُذِفَتِ الْيَاءُ لِسُكُونِهَا وَسُكُونِ الْوَاوِ، فَبَقِيَ: غُزُوا."]]},{"id":"ma11_16","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٦","segs":[["matn","وَكُلُّ وَاوٍ وَيَاءٍ مُتَحَرِّكَتَيْنِ، وَيَكُونُ مَا قَبْلَهُمَا حَرْفٌ صَحِيحٌ سَاكِنٌ؛ نُقِلَتْ حَرَكَتُهُمَا إِلَى الْحَرْفِ الصَّحِيحِ؛ نَحْوُ: يَقُولُ، وَيَكِيلُ، وَيَخَافُ؛ وَالْأَصْلُ: يَقْوُلُ، وَيَكْيِلُ، وَيَخْوَفُ."]]},{"id":"ma11_17","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٧","segs":[["matn","نُقِلَتْ حَرَكَتُهُمَا لِمَا قَبْلَهُمَا فِي الْكُلِّ، وَإِنَّمَا قُلِبَتْ وَاوُ يَخَافُ أَلِفًا؛ لِكَوْنِ سُكُونِهَا غَيْرَ أَصْلِيٍّ، وَانْفِتَاحِ مَا قَبْلَهَا."]]},{"id":"ma11_18","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٨","segs":[["matn","وَكُلُّ وَاوٍ وَيَاءٍ إِذَا كَانَتَا مُتَحَرِّكَتَيْنِ، وَوَقَعَتَا فِي لَامِ الْفِعْلِ، وَمَا قَبْلَهُمَا حَرْفٌ صَحِيحٌ مُتَحَرِّكٌ؛ أُسْكِنَتَا مَا لَمْ يَكُنْ مَنْصُوبًا، نَحْوُ: يَغْزُو، وَيَرْمِي، وَيَخْشَى؛ لِاسْتِثْقَالِ الضَّمَّةِ عَلَى الْوَاوِ وَالْيَاءِ."]]},{"id":"ma11_19","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ١٩","segs":[["matn","وَالْأَصْلُ: يَغْزُوُ، وَيَرْمِيُ، وَيَخْشَيُ، وَقُلِبَتْ يَاءُ يَخْشَى أَلِفًا؛ لِتَحَرُّكِهَا وَانْفِتَاحِ مَا قَبْلَهَا."]]},{"id":"ma11_20","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٠","segs":[["matn","وَيَتَحَرَّكُ الْوَاوُ وَالْيَاءُ إِذَا كَانَتَا مَنْصُوبَتَيْنِ، نَحْوُ: لَنْ يَغْزُوَ، وَلَنْ يَرْمِيَ، وَلَنْ يَخْشَى؛ لِخِفَّةِ الْفَتْحَةِ عَلَيْهِمَا، وَتَقُولُ فِي التَّثْنِيَةِ: يَغْزُوَانِ، وَيَرْمِيَانِ، وَيَخْشَيَانِ."]]},{"id":"ma11_21","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢١","segs":[["matn","وَتَقُولُ فِي جَمْعِ الْمُذَكَّرِ: يَغْزُونَ، وَيَرْمُونَ، وَيَخْشَوْنَ، وَالْأَصْلُ: يَغْزُوُونَ، وَيَرْمِيُونَ، وَيَخْشَيُونَ، فَأُسْكِنَتِ الْوَاوُ وَالْيَاءُ لِوُقُوعِهِمَا فِي لَامِ الْفِعْلِ، وَاسْتِثْقَالِ الضَّمَّةِ عَلَى الْوَاوِ وَالْيَاءِ، وَقُلِبَتْ يَاءُ يَخْشَيُونَ أَلِفًا لِتَحَرُّكِهَا، وَانْفِتَاحِ مَا قَبْلَهَا."]]},{"id":"ma11_22","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٢","segs":[["matn","فَاجْتَمَعَ سَاكِنَانِ: الْوَاوُ وَالْيَاءُ، وَبَعْدَهُمَا وَاوُ الْجَمْعِ، فَحُذِفَ مَا كَانَ قَبْلَ وَاوِ الْجَمْعِ، وَضُمَّتِ الْمِيمُ مِنْ يَرْمُونَ لِتَصِحَّ وَاوُ الْجَمْعِ."]]},{"id":"ma11_23","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٣","segs":[["matn","وَتَقُولُ فِي وَاحِدَةِ الْمُخَاطَبَةِ: تَغْزِينَ، وَالْأَصْلُ: تَغْزُوِينَ؛ فَأُسْكِنَتِ الزَّايُ لِاسْتِثْقَالِ الضَّمَّةِ عَلَى الزَّايِ قَبْلَ كَسْرَةِ الْوَاوِ، وَنُقِلَتْ كَسْرَةُ الْوَاوِ إِلَى الزَّايِ، وَحُذِفَتِ الْوَاوُ لِسُكُونِهَا وَسُكُونِ الْيَاءِ."]]},{"id":"ma11_24","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٤","segs":[["matn","وَتَقُولُ فِي اسْمِ الْفَاعِلِ مِنَ الْأَجْوَفِ: قَائِلٌ، وَكَائِلٌ، وَالْأَصْلُ: قَاوِلٌ وَكَايِلٌ، وَكَانَ فِي الْمَاضِي: قَالَ، وَكَالَ، فَزِيدَتِ الْأَلِفُ لِاسْمِ الْفَاعِلِ، فَاجْتَمَعَ أَلِفَانِ."]]},{"id":"ma11_25","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٥","segs":[["matn","أَحَدُهُمَا أَلِفُ اسْمِ الْفَاعِلِ، وَالْآخَرُ الْأَلِفُ الْمَقْلُوبَةُ مِنْ عَيْنِ الْفِعْلِ؛ فَقُلِبَتِ الْأَلِفُ الْمَقْلُوبَةُ مِنْ عَيْنِ الْفِعْلِ هَمْزَةً، فَصَارَ: قَائِلٌ، وَكَذَلِكَ: كَائِلٌ."]]},{"id":"ma11_26","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٦","segs":[["matn","وَاسْمُ الْفَاعِلِ مِنَ النَّاقِصِ مَنْصُوبٌ فِي حَالَةِ النَّصْبِ، نَحْوُ: رَأَيْتُ غَازِيًا وَرَامِيًا، فَلَا يَتَغَيَّرُ صِيغَتُهُمَا، وَتَقُولُ فِي الرَّفْعِ وَالْجَرِّ: هَذَا غَازٍ وَرَامٍ، وَمَرَرْتُ بِغَازٍ وَرَامٍ."]]},{"id":"ma11_27","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٧","segs":[["matn","وَالْأَصْلُ: غَازِيٌ وَرَامِيٌ؛ فَأُسْكِنَتِ الْيَاءُ كَمَا ذَكَرْنَا، فَاجْتَمَعَ سَاكِنَانِ؛ الْيَاءُ وَالتَّنْوِينُ، فَحُذِفَتِ الْيَاءُ وَبَقِيَ التَّنْوِينُ."]]},{"id":"ma11_28","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٨","segs":[["matn","فَإِنْ أَدْخَلْتَ الْأَلِفَ وَاللَّامَ سَقَطَ التَّنْوِينُ، وَتَعُودُ الْيَاءُ سَاكِنَةً؛ لِأَنَّ الْأَلِفَ وَاللَّامَ لَا يَجْتَمِعُ مَعَ التَّنْوِينِ، فَتَقُولُ: هَذَا الْغَازِي وَالرَّامِي، وَمَرَرْتُ بِالْغَازِي وَالرَّامِي."]]},{"id":"ma11_29","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٢٩","segs":[["matn","وَتَقُولُ فِي اسْمِ الْمَفْعُولِ مِنَ الْأَجْوَفِ: مَقُولٌ، وَالْأَصْلُ: مَقْوُولٌ؛ فَفُعِلَ بِهِ كَمَا ذَكَرْنَا، وَتَقُولُ مِنْ بِنَاءِ الْيَائِيِّ: مَكِيلٌ، وَالْأَصْلُ: مَكْيُولٌ."]]},{"id":"ma11_30","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٠","segs":[["matn","فَنُقِلَتْ حَرَكَةُ الْيَاءِ إِلَى الْكَافِ، فَحُذِفَتِ الْيَاءُ لِاجْتِمَاعِ السَّاكِنَيْنِ، وَكُسِرَتِ الْكَافُ لِتَدُلَّ عَلَى الْيَاءِ الْمَحْذُوفَةِ، فَلَمَّا انْكَسَرَتِ الْكَافُ صَارَتْ وَاوُ الْمَفْعُولِ يَاءً؛ لِسُكُونِهَا وَانْكِسَارِ مَا قَبْلَهَا."]]},{"id":"ma11_31","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣١","segs":[["matn","وَإِذَا اجْتَمَعَتِ الْوَاوَانِ وَالْأُولَى سَاكِنَةٌ، وَالثَّانِيَةُ مُتَحَرِّكَةٌ؛ أُدْغِمَتِ الْأُولَى فِي الثَّانِيَةِ، نَحْوُ: مَغْزُوٌّ، وَالْأَصْلُ: مَغْزُووٌ."]]},{"id":"ma11_32","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٢","segs":[["matn","وَإِذَا اجْتَمَعَتِ الْوَاوُ وَالْيَاءُ، وَالْأُولَى سَاكِنَةٌ، وَالثَّانِيَةُ مُتَحَرِّكَةٌ؛ قُلِبَتِ الْوَاوُ يَاءً، وَكُسِرَ مَا قَبْلَ الْيَاءِ الْأُولَى، لِتَصِحَّ الْيَاءُ، وَأُدْغِمَتِ الْيَاءُ فِي الْيَاءِ، نَحْوُ: مَرْمِيٌّ، وَمَخْشِيٌّ؛ وَالْأَصْلُ: مَرْمُويٌ، وَمَخْشُويٌ."]]},{"id":"ma11_33","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٣","segs":[["matn","وَتَقُولُ فِي أَمْرِ الْغَائِبِ مِنَ الْأَجْوَفِ: لِيَقُلْ، وَالْأَصْلُ: لِيَقْوُلْ، فَنُقِلَتْ حَرَكَةُ الْوَاوِ إِلَى الْقَافِ، فَحُذِفَتِ الْوَاوُ لِسُكُونِهَا وَسُكُونِ اللَّامِ، فَصَارَتْ: لِيَقُلْ."]]},{"id":"ma11_34","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٤","segs":[["matn","وَتَقُولُ فِي أَمْرِ الْحَاضِرِ: قُلْ، وَالْأَصْلُ: اقْوُلْ؛ فَنُقِلَتْ حَرَكَةُ الْوَاوِ إِلَى الْقَافِ، وَحُذِفَتِ الْوَاوُ لِسُكُونِهَا وَسُكُونِ اللَّامِ، وَحُذِفَتِ الْهَمْزَةُ بِحَرَكَةِ الْقَافِ، فَصَارَتْ: قُلْ، وَتَقُولُ فِي التَّثْنِيَةِ: قُولَا، فَعَادَتِ الْوَاوُ لِحَرَكَةِ اللَّامِ."]]},{"id":"ma11_35","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٥","segs":[["matn","وَتَقُولُ فِي أَمْرِ الْغَائِبِ مِنَ النَّاقِصِ: لِيَغْزُ، وَلِيَرْمِ، وَفِي أَمْرِ الْحَاضِرِ: اغْزُ، وَارْمِ، بِحَذْفِ الْوَاوِ وَالْيَاءِ؛ لِأَنَّ جَزْمَ النَّاقِصِ وَوَقْفَهُ سُقُوطُ لَامِ فِعْلِهِ."]]},{"id":"ma11_36","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٦","segs":[["matn","وَفِي النَّاقِصِ الْوَاوِيِّ تُقْلَبُ الْوَاوُ يَاءً فِي الْمُسْتَقْبَلِ وَالْأَمْرِ وَالنَّهْيِ الْمَجْهُولَاتِ؛ لِأَنَّهُنَّ فُرُوعُ الْمَاضِي، وَفِي الْمَاضِي الْمَجْهُولِ تَصِيرُ الْوَاوُ يَاءً لِتَطَرُّفِهَا، وَانْكِسَارِ مَا قَبْلَهَا، نَحْوُ: غُزِيَ، وَالْأَصْلُ: غُزِوَ."]]},{"id":"ma11_37","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٧","segs":[["matn","وَأَمَّا الْمُعْتَلُّ الْفَاءِ: فَتَسْقُطُ فَاءُ فِعْلِهِ فِي الْمُسْتَقْبَلِ وَالْأَمْرِ وَالنَّهْيِ الْمَعْرُوفَاتِ، إِذَا كَانَ فَاءُ فِعْلِهِ وَاوًا مِنْ ثَلَاثَةِ أَبْوَابٍ:"]]},{"id":"ma11_38","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٨","segs":[["matn","فَعَلَ يَفْعِلُ بِفَتْحِ الْعَيْنِ فِي الْمَاضِي، وَكَسْرِهَا فِي الْغَابِرِ، نَحْوُ: وَعَدَ، يَعِدُ، وَفَعَلَ يَفْعَلُ بِفَتْحِ الْعَيْنِ فِي الْمَاضِي وَالْغَابِرِ، نَحْوُ: وَهَبَ، يَهَبُ."]]},{"id":"ma11_39","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٣٩","segs":[["matn","وَفَعِلَ يَفْعِلُ بِكَسْرِ الْعَيْنِ فِي الْمَاضِي وَالْغَابِرِ، نَحْوُ: وَرِثَ، يَرِثُ، وَتَقُولُ فِي الْأَمْرِ وَالنَّهْيِ: عِدْ، لَا تَعِدْ، وَتَقُولُ: هَبْ، لَا تَهَبْ، وَتَقُولُ: رِثْ، لَا تَرِثْ."]]},{"id":"ma11_40","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٠","segs":[["matn","وَقَدْ تَسْقُطُ الْوَاوُ مِنْ بَابِ فَعِلَ يَفْعَلُ بِكَسْرِ الْعَيْنِ فِي الْمَاضِي، وَفَتْحِهَا فِي الْغَابِرِ مِنْ لَفْظَيْنِ، نَحْوُ: وَطِئَ، يَطَأُ، وَوَسِعَ، يَسَعُ."]]},{"id":"ma11_41","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤١","segs":[["matn","وَأَمَّا اللَّفِيفُ الْمَقْرُونُ: فَحُكْمُ عَيْنِ فِعْلِهِ كَحُكْمِ الصَّحِيحِ لَا يَتَغَيَّرُ، وَحُكْمُ لَامِ فِعْلِهِ كَحُكْمِ لَامِ فِعْلِ النَّاقِصِ، نَحْوُ: طَوَى، يَطْوِي، وَتَقُولُ فِي الْأَمْرِ الْحَاضِرِ: اطْوِ بِحَذْفِ لَامِ الْفِعْلِ."]]},{"id":"ma11_42","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٢","segs":[["matn","وَحُكْمُ لَامِ فِعْلِهِ كَحُكْمِ لَامِ فِعْلِ النَّاقِصِ، مِثْلُ: رَوَى، يَرْوِي، وَتَقُولُ فِي الْأَمْرِ مِنْهُ: ارْوِ بِحَذْفِ لَامِ الْفِعْلِ."]]},{"id":"ma11_43","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٣","segs":[["matn","وَأَمَّا اللَّفِيفُ الْمَفْرُوقُ: فَحُكْمُ فَاءِ فِعْلِهِ كَحُكْمِ فَاءِ فِعْلِ الْمُعْتَلِّ، وَحُكْمُ لَامِ فِعْلِهِ كَحُكْمِ لَامِ فِعْلِ النَّاقِصِ، نَحْوُ: وَقَى، يَقِي."]]},{"id":"ma11_44","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٤","segs":[["matn","وَتَقُولُ فِي الْأَمْرِ الْحَاضِرِ: قِهْ؛ فَحُذِفَتْ فَاءُ فِعْلِهِ كَالْمُعْتَلِّ، وَحُذِفَتْ لَامُ فِعْلِهِ فِي الْجَزْمِ وَالْوَقْفِ كَالنَّاقِصِ؛ فَبَقِيَ الْقَافُ مَكْسُورَةً، وَزِيدَتِ الْهَاءُ عِنْدَ الْوَقْفِ فِي الْوَاحِدِ الْمُذَكَّرِ."]]},{"id":"ma11_45","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٥","segs":[["matn","وَتَقُولُ فِي التَّثْنِيَةِ: قِيَا، وَفِي الْجَمْعِ: قُوا، وَفِي الْوَاحِدَةِ الْحَاضِرَةِ الْمُؤَنَّثَةِ: قِي، وَفِي التَّثْنِيَةِ: قِيَانِ، وَفِي الْجَمْعِ الْمُؤَنَّثِ: قِينَ."]]},{"id":"ma11_46","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٦","segs":[["matn","وَأَمَّا الْمُضَاعَفُ: إِذَا كَانَ عَيْنُ فِعْلِهِ سَاكِنَةً وَلَامُهُ مُتَحَرِّكَةً، أَوْ كِلْتَاهُمَا مُتَحَرِّكَتَيْنِ؛ فَالْإِدْغَامُ لَازِمٌ، نَحْوُ: مَدَّ، يَمُدُّ، وَالْأَصْلُ: مَدَدَ يَمْدُدُ."]]},{"id":"ma11_47","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٧","segs":[["matn","فَنُقِلَتْ حَرَكَةُ الدَّالِ الْأُولَى فِي الْمُسْتَقْبَلِ إِلَى الْمِيمِ، وَبَقِيَتِ الدَّالُ سَاكِنَةً، فَأُدْغِمَتِ الدَّالُ الْأُولَى فِي الثَّانِيَةِ، فَصَارَ: يَمُدُّ."]]},{"id":"ma11_48","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٨","segs":[["matn","وَإِنْ كَانَ عَيْنُ فِعْلِهِ مُتَحَرِّكَةً وَلَامُهُ سَاكِنَةً؛ فَالْإِظْهَارُ لَازِمٌ، نَحْوُ: مَدَدْنَ إِلَى مَدَدْنَا."]]},{"id":"ma11_49","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٤٩","segs":[["matn","وَإِنْ كَانَتَا سَاكِنَتَيْنِ؛ حُرِّكَتِ الدَّالُ الثَّانِيَةُ، وَأُدْغِمَتِ الْأُولَى فِيهَا، نَحْوُ: لَمْ يَمُدَّ، وَالْأَصْلُ: لَمْ يَمْدُدْ، فَنُقِلَتْ حَرَكَةُ الدَّالِ الْأُولَى إِلَى الْمِيمِ، فَبَقِيَتَا سَاكِنَتَيْنِ، فَحُرِّكَتِ الدَّالُ الثَّانِيَةُ، وَأُدْغِمَتِ الْأُولَى فِي الثَّانِيَةِ."]]},{"id":"ma11_50","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٠","segs":[["matn","ثُمَّ فُتِحَتِ الدَّالُ الثَّانِيَةُ؛ لِأَنَّ الْفَتْحَةَ أَخَفُّ الْحَرَكَاتِ، وَيَجُوزُ تَحْرِيكُهَا بِالضَّمِّ وَالْكَسْرِ، كَمَا يُذْكَرُ فِي الْأَمْرِ."]]},{"id":"ma11_51","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥١","segs":[["matn","وَتَقُولُ فِي الْأَمْرِ مِنْ يَفْعُلُ بِضَمِّ الْعَيْنِ: مُدُّ بِضَمِّ الدَّالِ، وَمُدَّ بِفَتْحِهَا، وَمُدِّ بِكَسْرِهَا، فَالْمِيمُ مَضْمُومَةٌ فِي الثَّلَاثِ، وَيَجُوزُ: امْدُدْ بِالْإِظْهَارِ."]]},{"id":"ma11_52","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٢","segs":[["matn","وَتَقُولُ فِي الْأَمْرِ مِنْ يَفْعِلُ بِكَسْرِ الْعَيْنِ: فِرِّ بِالْكَسْرِ، وَفِرَّ بِالْفَتْحِ، وَالْفَاءُ مَكْسُورَةٌ فِيهِمَا، وَيَجُوزُ: افْرِرْ بِالْإِظْهَارِ."]]},{"id":"ma11_53","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٣","segs":[["matn","وَتَقُولُ فِي الْأَمْرِ مِنْ يَفْعَلُ بِفَتْحِ الْعَيْنِ: عَضَّ بِالْفَتْحِ، وَعَضِّ بِالْكَسْرِ، وَالْعَيْنُ مَفْتُوحَةٌ فِيهِمَا، وَيَجُوزُ: اعْضَضْ بِالْإِظْهَارِ."]]},{"id":"ma11_54","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٤","segs":[["matn","وَتَقُولُ فِي الْمَاضِي مِنْ أَفْعَلَ يُفْعِلُ: أَحَبَّ، يُحِبُّ، وَالْأَصْلُ: أَحْبَبَ يُحْبِبُ، فَنُقِلَتْ حَرَكَةُ الْبَاءِ إِلَى الْحَاءِ، وَأُدْغِمَتِ الْبَاءُ فِي الْبَاءِ."]]},{"id":"ma11_55","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٥","segs":[["matn","وَتَقُولُ فِي الْأَمْرِ: أَحِبَّ وَأَحْبِبْ بِالْإِدْغَامِ وَالْإِظْهَارِ، وَكُلَّمَا أَدْغَمْتَ حَرْفًا فِي حَرْفٍ أَدْخَلْتَ بَدَلَهُ تَشْدِيدًا."]]},{"id":"ma11_56","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٦","segs":[["matn","وَأَمَّا الْمَهْمُوزُ: فَإِنْ كَانَتِ الْهَمْزَةُ سَاكِنَةً يَجُوزُ تَرْكُهَا عَلَى حَالِهَا، وَيَجُوزُ قَلْبُهَا: فَإِنْ كَانَ مَا قَبْلَهَا مَفْتُوحًا قُلِبَتْ أَلِفًا، وَإِنْ كَانَ مَكْسُورًا قُلِبَتْ يَاءً، وَإِنْ كَانَ مَضْمُومًا قُلِبَتْ وَاوًا، نَحْوُ: يَاكُلُ، وَيُومِنُ، وَايذَنْ أَمْرٌ مِنْ أَذِنَ."]]},{"id":"ma11_57","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٧","segs":[["matn","وَإِنْ كَانَتِ الْهَمْزَةُ مُتَحَرِّكَةً، فَإِنْ كَانَ مَا قَبْلَهَا حَرْفًا صَحِيحًا مُتَحَرِّكًا لَا تَتَغَيَّرُ الْهَمْزَةُ كَالصَّحِيحِ، نَحْوُ: قَرَأَ، يَقْرَأُ."]]},{"id":"ma11_58","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٨","segs":[["matn","وَإِنْ كَانَ مَا قَبْلَهَا حَرْفًا صَحِيحًا سَاكِنًا: يَجُوزُ تَرْكُهَا عَلَى حَالِهَا، وَيَجُوزُ نَقْلُ حَرَكَتِهَا إِلَى مَا قَبْلَهَا، مِثَالُهُ قَوْلُهُ تَعَالَى: وَسَلِ الْقَرْيَةَ، وَالْأَصْلُ: وَاسْأَلِ الْقَرْيَةَ."]]},{"id":"ma11_59","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٥٩","segs":[["matn","فَنُقِلَتْ حَرَكَةُ الْهَمْزَةِ إِلَى السِّينِ فَحُذِفَتِ الْهَمْزَةُ لِسُكُونِهَا وَسُكُونِ اللَّامِ بَعْدَهَا، وَقَدْ قُرِئَ بِإِثْبَاتِ الْهَمْزَةِ، نَحْوُ: ﴿وَاسْأَلِ الْقَرْيَةَ﴾، وَتَرْكِهَا."]]},{"id":"ma11_60","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٦٠","segs":[["matn","وَتَقُولُ فِي الْأَمْرِ مِنَ الْأَخْذِ وَالْأَكْلِ وَالْأَمْرِ: خُذْ، وَكُلْ، وَمُرْ، عَلَى غَيْرِ الْقِيَاسِ."]]},{"id":"ma11_61","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٦١","segs":[["matn","وَبَاقِي تَصْرِيفِ الْمَهْمُوزِ عَلَى قِيَاسِ الصَّحِيحِ، وَكُلَّمَا وَجَدْتَ فِعْلًا غَيْرَ الصَّحِيحِ فَقِسْهُ عَلَى الصَّحِيحِ فِي جَمِيعِ الْوُجُوهِ الَّتِي ذَكَرْنَاهَا فِي بَابِ الصَّحِيحِ مِنَ التَّصْرِيفِ."]]},{"id":"ma11_62","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٦٢","segs":[["matn","فَإِنِ اقْتَضَى الْقِيَاسُ إِلَى إِبْدَالِ حَرْفٍ، أَوْ نَقْلٍ، أَوْ إِسْكَانٍ؛ فَافْعَلْ عَلَى مُقْتَضَى الْقِيَاسِ، وَإِلَّا صَرِّفِ الْفِعْلَ الْغَيْرَ الصَّحِيحِ كَالصَّحِيحِ."]]},{"id":"ma11_63","label":"بَابُ الْمُعْتَلَّاتِ وَالْمُضَاعَفِ وَالْمَهْمُوزِ · ٦٣","segs":[["matn","وَقَدْ يَكُونُ فِي بَعْضِ الْمَوَاضِعِ لَا تَتَغَيَّرُ الْمُعْتَلَّاتُ فِيهِ مَعَ وُجُودِ الْمُقْتَضِي، نَحْوُ: عَوِرَ، وَاعْتَوَرَ، وَاسْتَوَى، وَغَيْرِ ذَلِكَ، وَبَعْضُهَا لَا يَتَغَيَّرُ لِصِحَّةِ الْبِنَاءِ، وَبَعْضُهَا لِعِلَّةٍ أُخْرَى."]]}]}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
